FRI = ("п'ятниц", "пʼятниц", "п’ятниц")


def mc(lead, text, question, options, answer):
    body = "\n".join(f"{'АБВГ'[i]}) {o}" for i, o in enumerate(options))
    return f"{lead}\nТекст: «{text}»\nПитання: {question}\n{body}", answer


